package com.simibubi.create.content.equipment.blueprint;

import com.simibubi.create.test.*;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.fabricmc.fabric.api.transfer.v1.item.*;
import net.fabricmc.fabric.api.transfer.v1.transaction.Transaction;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.crafting.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;

/** Actual native callback/save/admission boundaries. Proposed GameTests, runtime UNRUN. */
public final class BlueprintDeliveryGameTests {
 private static BlueprintEntity blueprint(GameTestHelper h,Item input){var pos=h.absolutePos(new BlockPos(3,3,3));h.getLevel().setBlockAndUpdate(pos.north(),Blocks.STONE.defaultBlockState());var entity=new BlueprintEntity(h.getLevel(),pos,Direction.SOUTH,Direction.DOWN);h.assertTrue(entity.size()==1&&h.getLevel().addFreshEntity(entity),"Actual native source blueprint endpoint");var ghosts=new SimpleContainer(11);ghosts.setItem(0,new ItemStack(input));ghosts.setItem(9,new ItemStack(BlueprintTestFixtures.OUTPUT));entity.getSection(0).save(ghosts,false);return entity;}
 private static NativeSurvivalTestPlayer player(GameTestHelper h,BlueprintEntity blueprint){var joined=NativeSurvivalTestPlayer.join(h,blueprint.position().add(0,0,2));joined.player().getInventory().clearContent();return joined;}
 private static int count(net.minecraft.world.entity.player.Player player,Item item){return player.getInventory().countItem(item);}
 private static void fill(net.minecraft.world.entity.player.Player player){for(int i=0;i<36;i++)player.getInventory().setItem(i,new ItemStack(Items.STONE,64));player.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.MILK_BUCKET));}
 private static void craft(NativeSurvivalTestPlayer joined,BlueprintEntity blueprint,BlueprintTestFixtures.Mode mode,BlueprintTestFixtures.NativeRefusal error,BlueprintTestFixtures.Observation observation){BlueprintTestFixtures.with(new BlueprintTestFixtures.Scope(joined.player(),blueprint.getSection(0),mode,error,observation),()->joined.player().interactOn(blueprint,InteractionHand.MAIN_HAND,Vec3.ZERO));}
 private static int encodedOwned(CompoundTag data,Item item,net.minecraft.server.level.ServerLevel level){int count=0;var ops=level.registryAccess().createSerializationContext(NbtOps.INSTANCE);for(var tag:data.getListOrEmpty("Pending")){var entry=(CompoundTag)tag;var loose=entry.read("Loose",ItemStack.OPTIONAL_CODEC,ops).orElse(ItemStack.EMPTY);if(loose.is(item))count+=loose.getCount();var entity=entry.getCompoundOrEmpty("Entity");for(var key:List.of("Item","Box")){var stack=entity.read(key,ItemStack.OPTIONAL_CODEC,ops).orElse(ItemStack.EMPTY);if(stack.is(item))count+=stack.getCount();}}return count;}
 private static void retry(NativeSurvivalTestPlayer joined){var player=joined.player();var data=BlueprintDelivery.get(player.level());for(var receipt:List.copyOf(pending(data)))data.deliver(player,receipt);}
 @SuppressWarnings("unchecked") private static List<BlueprintDelivery.Receipt> pending(BlueprintDelivery data){try{var field=BlueprintDelivery.class.getDeclaredField("entries");field.setAccessible(true);return (List<BlueprintDelivery.Receipt>)field.get(data);}catch(ReflectiveOperationException error){throw new AssertionError(error);}}
 @GameTest public void actualNativeRemainderRunsAfterCraftedHookAndSurvivesHookError(GameTestHelper h){var blueprint=blueprint(h,BlueprintTestFixtures.NATIVE_MILK);try(var joined=player(h,blueprint)){var player=joined.player();player.getInventory().setItem(0,new ItemStack(BlueprintTestFixtures.NATIVE_MILK));var observation=new BlueprintTestFixtures.Observation();var error=new BlueprintTestFixtures.NativeRefusal();boolean caught=false;try{craft(joined,blueprint,BlueprintTestFixtures.Mode.ERROR,error,observation);}catch(BlueprintTestFixtures.NativeRefusal actual){caught=actual==error;}h.assertTrue(caught&&observation.calls==1&&observation.remainders==1&&count(player,BlueprintTestFixtures.NATIVE_MILK)==0&&count(player,BlueprintTestFixtures.OUTPUT)==4&&count(player,Items.BUCKET)==1,"Actual source native hook precedes genuine ingredient remainder callback; exact hook error does not lose the paid bucket remainder");h.assertTrue(BlueprintDeliveryTestFixtures.capture(h.getLevel()).getListOrEmpty("Crafts").isEmpty(),"All paid remainder ownership publishes atomically before debt retires");}h.succeed();}
 @GameTest public void saveInsideNativeTransferHookCannotSerializeSecondOutputClaim(GameTestHelper h){var blueprint=blueprint(h,Items.MILK_BUCKET);try(var joined=player(h,blueprint)){var player=joined.player();player.getInventory().setItem(0,new ItemStack(Items.MILK_BUCKET));var observation=new BlueprintTestFixtures.Observation();craft(joined,blueprint,BlueprintTestFixtures.Mode.SAVE_TRANSFER,null,observation);h.assertTrue(player.getInventory().getItem(20)==observation.result&&count(player,BlueprintTestFixtures.OUTPUT)==4&&encodedOwned(observation.saved,BlueprintTestFixtures.OUTPUT,h.getLevel())==0,"Reentrant native save reconciles the exact result reference already installed in actual player inventory; no second durable cargo claim");var crafts=observation.saved.getListOrEmpty("Crafts");h.assertTrue(crafts.size()==1&&crafts.getCompoundOrEmpty(0).getBooleanOr("HookAttempted",false),"Only metadata continuation remains and native hook attempt was persisted before callback entry");}h.succeed();}
 @GameTest public void nativeRefusalRetainsExactProspectiveEntityAndSingleDurablePayload(GameTestHelper h){var blueprint=blueprint(h,Items.MILK_BUCKET);try(var joined=player(h,blueprint)){var player=joined.player();fill(player);var nativeObservation=new BlueprintDeliveryTestFixtures.Observation();BlueprintDeliveryTestFixtures.with(h.getLevel(),BlueprintDeliveryTestFixtures.Mode.REFUSE,nativeObservation,()->craft(joined,blueprint,BlueprintTestFixtures.Mode.NORMAL,null,new BlueprintTestFixtures.Observation()));var actual=nativeObservation.endpoint;var saved=BlueprintDeliveryTestFixtures.capture(h.getLevel());h.assertTrue(nativeObservation.attempts==1&&actual instanceof ItemEntity&&!actual.isRemoved()&&h.getLevel().getEntity(actual.getUUID())==null&&encodedOwned(saved,BlueprintTestFixtures.OUTPUT,h.getLevel())==4,"Actual add false retains same unadmitted native item/UUID and exactly one full current durable result claim");retry(joined);h.assertTrue(h.getLevel().getEntity(actual.getUUID())==actual&&encodedOwned(BlueprintDeliveryTestFixtures.capture(h.getLevel()),BlueprintTestFixtures.OUTPUT,h.getLevel())==0,"Retry admits the exact original physical endpoint once, with pure receipt removal at native section insertion");}h.succeed();}
 @GameTest public void removedRejectedProspectiveEndpointKeepsOnlyItsCurrentMutatedCargo(GameTestHelper h){var blueprint=blueprint(h,Items.MILK_BUCKET);try(var joined=player(h,blueprint)){fill(joined.player());var observation=new BlueprintDeliveryTestFixtures.Observation();BlueprintDeliveryTestFixtures.with(h.getLevel(),BlueprintDeliveryTestFixtures.Mode.MUTATE_REMOVE_REFUSE,observation,()->craft(joined,blueprint,BlueprintTestFixtures.Mode.NORMAL,null,new BlueprintTestFixtures.Observation()));var rejected=observation.endpoint;var saved=BlueprintDeliveryTestFixtures.capture(h.getLevel());h.assertTrue(rejected.isRemoved()&&h.getLevel().getEntity(rejected.getUUID())==null&&encodedOwned(saved,BlueprintTestFixtures.OUTPUT,h.getLevel())==3,"Removed prospective object is no acceptance proof: only its actual mutated three-item current cargo becomes durable loose ownership");retry(joined);var drops=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(joined.player().blockPosition()).inflate(3));h.assertTrue(drops.stream().filter(entity->entity.getItem().is(BlueprintTestFixtures.OUTPUT)).mapToInt(entity->entity.getItem().getCount()).sum()==3&&h.getLevel().getEntity(rejected.getUUID())==null&&encodedOwned(BlueprintDeliveryTestFixtures.capture(h.getLevel()),BlueprintTestFixtures.OUTPUT,h.getLevel())==0,"A future real factory handles current loose cargo without reviving or reconstructing the rejected entity/old count");}h.succeed();}
 @GameTest public void actualSectionInsertionRetiresReceiptBeforeEarlyNativeOnCreatedSave(GameTestHelper h){var blueprint=blueprint(h,Items.MILK_BUCKET);try(var joined=player(h,blueprint)){fill(joined.player());var observation=new BlueprintDeliveryTestFixtures.Observation();BlueprintDeliveryTestFixtures.with(h.getLevel(),BlueprintDeliveryTestFixtures.Mode.EARLY_SAVE,observation,()->craft(joined,blueprint,BlueprintTestFixtures.Mode.NORMAL,null,new BlueprintTestFixtures.Observation()));h.assertTrue(observation.exactInsertion&&observation.notYetVisible&&encodedOwned(observation.saved,BlueprintTestFixtures.OUTPUT,h.getLevel())==0&&h.getLevel().getEntity(observation.endpoint.getUUID())==observation.endpoint,"Actual native section proof commits receipt before early onCreated and before visible UUID lookup, so a native reentrant save has no duplicate durable claim");}h.succeed();}
 @GameTest public void lateNativeOnCreatedThrowCannotRestoreAnAlreadyAcceptedResultClaim(GameTestHelper h){var blueprint=blueprint(h,Items.MILK_BUCKET);try(var joined=player(h,blueprint)){fill(joined.player());var observation=new BlueprintDeliveryTestFixtures.Observation();boolean caught=false;try{BlueprintDeliveryTestFixtures.with(h.getLevel(),BlueprintDeliveryTestFixtures.Mode.EARLY_THROW,observation,()->craft(joined,blueprint,BlueprintTestFixtures.Mode.NORMAL,null,new BlueprintTestFixtures.Observation()));}catch(BlueprintDeliveryTestFixtures.NativeRefusal actual){caught=actual==observation.error;}h.assertTrue(caught&&observation.exactInsertion&&encodedOwned(observation.saved,BlueprintTestFixtures.OUTPUT,h.getLevel())==0&&encodedOwned(BlueprintDeliveryTestFixtures.capture(h.getLevel()),BlueprintTestFixtures.OUTPUT,h.getLevel())==0,"Exact native callback error propagates after real section acceptance; module cannot restore or redeliver that owned output even if visible-index creation did not finish");}h.succeed();}
 @GameTest public void nativeRemainderErrorLeavesRetryableDebtWithoutRepeatingAttemptedCraftedHook(GameTestHelper h){var blueprint=blueprint(h,BlueprintTestFixtures.NATIVE_MILK);try(var joined=player(h,blueprint)){var player=joined.player();player.getInventory().setItem(0,new ItemStack(BlueprintTestFixtures.NATIVE_MILK));var observation=new BlueprintTestFixtures.Observation();var error=new BlueprintTestFixtures.NativeRefusal();boolean caught=false;try{craft(joined,blueprint,BlueprintTestFixtures.Mode.REMAINDER_ERROR,error,observation);}catch(BlueprintTestFixtures.NativeRefusal actual){caught=actual==error;}var saved=BlueprintDeliveryTestFixtures.capture(h.getLevel());h.assertTrue(caught&&observation.calls==1&&observation.remainders==1&&count(player,BlueprintTestFixtures.NATIVE_MILK)==0&&count(player,BlueprintTestFixtures.OUTPUT)==0&&encodedOwned(saved,BlueprintTestFixtures.OUTPUT,h.getLevel())==4&&saved.getListOrEmpty("Crafts").size()==1,"Actual remaining callback failure retains one paid full result and retryable exact native-input recipe debt; output not delivered early");var data=BlueprintDelivery.get(h.getLevel());var paid=pending(data).getFirst();BlueprintTestFixtures.with(new BlueprintTestFixtures.Scope(player,blueprint.getSection(0),BlueprintTestFixtures.Mode.NORMAL,null,observation),()->data.finishCraft(player,paid,null));h.assertTrue(observation.calls==1&&observation.remainders==2&&count(player,BlueprintTestFixtures.OUTPUT)==4&&count(player,Items.BUCKET)==1&&BlueprintDeliveryTestFixtures.capture(h.getLevel()).getListOrEmpty("Crafts").isEmpty(),"Actual manager recipe retry computes native remainders after attempted hook without running that hook again or restoring paid input");}h.succeed();}
 @GameTest public void decodedUnattemptedPaidContinuationRejectsNativeCraftReentryBeforeAnotherPayment(GameTestHelper h){var blueprint=blueprint(h,Items.MILK_BUCKET);try(var joined=player(h,blueprint)){var player=joined.player();player.getInventory().setItem(0,new ItemStack(Items.MILK_BUCKET));player.getInventory().setItem(1,new ItemStack(Items.MILK_BUCKET));var data=BlueprintDelivery.get(h.getLevel());var grid=new ArrayList<ItemStack>(Collections.nCopies(9,ItemStack.EMPTY));grid.set(0,new ItemStack(Items.MILK_BUCKET));var input=CraftingInput.of(3,3,grid);var recipe=h.getLevel().getServer().getRecipeManager().getRecipeFor(RecipeType.CRAFTING,input,h.getLevel()).orElseThrow();try(var transaction=Transaction.openOuter()){h.assertTrue(PlayerInventoryStorage.of(player).getSlot(0).extract(ItemVariant.of(Items.MILK_BUCKET),1,transaction)==1,"Actual native source input pays once");data.ownCraft(player,recipe.value().assemble(input),recipe,grid,transaction);transaction.commit();}var saved=BlueprintDeliveryTestFixtures.capture(h.getLevel());h.assertTrue(saved.getListOrEmpty("Crafts").size()==1&&!saved.getListOrEmpty("Crafts").getCompoundOrEmpty(0).getBooleanOr("HookAttempted",true),"Native save before hook preserves genuine paid unattempted continuation");BlueprintDeliveryTestFixtures.installDecoded(h.getLevel(),saved);data=BlueprintDelivery.get(h.getLevel());var decoded=data;var receipt=pending(data).getFirst();var observation=new BlueprintTestFixtures.Observation();BlueprintTestFixtures.with(new BlueprintTestFixtures.Scope(player,blueprint.getSection(0),BlueprintTestFixtures.Mode.RECURSE,null,observation),()->decoded.finishCraft(player,receipt,null));h.assertTrue(observation.calls==1&&observation.recursiveCrafts==0&&count(player,Items.MILK_BUCKET)==1&&count(player,BlueprintTestFixtures.OUTPUT)==4&&count(player,Items.BUCKET)==1,"Actual first hook after native decode enters continuation actor guard; callback reentry cannot debit remaining original input");}h.succeed();}
}
